import { z } from 'zod';

export const SkillCreationContext = z.object({
  creationAttemptId: z.string().regex(/^creation-[a-f0-9-]{36}$/),
  entryType: z.enum(['A', 'B', 'C']),
  suggestionId: z.string().max(200).optional(),
}).strict();
export type SkillCreationContext = z.infer<typeof SkillCreationContext>;

// A closed allowlist. Neither package prose nor thread/turn identifiers belong here.
const id = z.string().min(1).max(200).optional();
export const SkillTelemetryProperties = z.object({
  creation_attempt_id: id, entry_type: z.enum(['A', 'B', 'C']).optional(), suggestion_id: id,
  submission_attempt_id: id, submission_index: z.number().int().nonnegative().optional(),
  draft_id: id, draft_revision_id: id, installation_id: id, instance_id: id, revision_id: id,
  invocation_id: id, invocation: z.enum(['explicit', 'implicit']).optional(),
  source_type: z.enum(['folder', 'zip', 'git', 'draft', 'bundled']).optional(),
  phase: z.enum(['generation', 'review', 'test']).optional(),
  outcome: z.enum(['passed', 'rejected', 'synced', 'merge-required', 'failed']).optional(),
  status: z.enum(['completed', 'interrupted', 'failed']).optional(),
  issue_codes: z.array(z.string().max(80)).max(100).optional(), issue_count: z.number().int().nonnegative().optional(),
  changed_file_count: z.number().int().nonnegative().optional(),
  delete_reason: z.enum(['user', 'thread_deleted']).optional(),
  evidence: z.literal('reported-leaf-completed').optional(),
  effective_step_completed: z.boolean().optional(),
}).strict();
export type SkillTelemetryProperties = z.infer<typeof SkillTelemetryProperties>;
export const SkillTelemetryEvent = z.object({
  eventId: z.string().min(1).max(200), occurredAt: z.number().int().nonnegative(), schemaVersion: z.literal(2),
  event: z.enum(['skill_creation_entry_opened', 'skill_creation_started', 'skill_creation_intent_detected',
    'skill_creation_question_asked', 'skill_creation_cancelled', 'skill_draft_validation_completed', 'skill_draft_submit_rejected',
    'skill_draft_generated', 'skill_draft_install_started', 'skill_draft_installed', 'personal_skill_updated', 'skill_draft_superseded', 'skill_draft_writeback',
    'personal_skill_deleted', 'skill_save_suggestion_shown', 'skill_save_suggestion_gate_missed',
    'skill_save_suggestion_accepted', 'skill_save_suggestion_dismissed',
    'skill_invocation', 'skill_effective_use', 'personal_skill_test_started', 'personal_skill_test_completed', 'personal_skill_test_finished']),
  properties: SkillTelemetryProperties,
}).strict();
export type SkillTelemetryEvent = z.infer<typeof SkillTelemetryEvent>;
